-- Four published articles. Run once in the Supabase SQL editor. Safe to re-run:
-- articles whose web address already exists are skipped.

with draft as (
  insert into public.article_drafts (document, published_revision)
  values ($article${"title": "The coat that does all the work", "slug": "the-coat-that-does-all-the-work", "emphasis": "all the work", "kicker": "Outerwear", "dek": "From November to March, the coat is the outfit. Choose it like you mean it.", "author": "The Curated Capsule", "publishedAt": "2026-11-20", "cover": "/images/articles/the-coat-that-does-all-the-work/cover.jpg", "coverAlt": "Model in a grey tailored coat and cropped top photographed from below", "products": ["trench", "suit-jacket", "anorak"], "body": "Here is the honest truth about winter dressing: for four months of the year, almost nobody sees what you are wearing underneath. They see the coat. On the walk to work, across the table at lunch, in every photo taken outside. Which is why it deserves more thought than anything else in the wardrobe.\n\n## Start with the shoulder\n\nA good coat is decided at the shoulder. Too narrow and it pulls the moment you lift your arms; too wide and it swallows you. Look for a line that sits just past your own shoulder, so a knit fits underneath without the sleeves bunching. If you can cross your arms comfortably, it fits.\n\n![Model in a burgundy blazer and black leather gloves seated inside a glass box](/images/articles/the-coat-that-does-all-the-work/burgundy.jpg)\n\n*Colour works hardest on outerwear: a deep burgundy reads as neutral by December.*\n\n## Long, short, or both\n\nIf you only buy one, buy it long enough to cover a skirt or dress — just below the knee is the most forgiving length. A cropped jacket is the second coat, the one for clear, cold days when you want to show off trousers with a good line.\n\n> Buy the coat for the coldest week of the year, not the mildest.\n\n## Fabric over finish\n\nWool with a little cashmere, a dense melton, or a leather that has been properly finished will outlast almost anything else you own. Trends sit better on the things you change often — the scarf, the bag, the shoe — and the coat can simply be very, very good.\n"}$article$::jsonb, 1)
  on conflict (slug) do nothing
  returning id, slug, document
)
insert into public.articles (id, slug, document)
select id, slug, document from draft;

with draft as (
  insert into public.article_drafts (document, published_revision)
  values ($article${"title": "Satin after dark", "slug": "satin-after-dark", "emphasis": "after dark", "kicker": "Party season", "dek": "One slip dress, four ways to wear it from the first invitation to New Year's Eve.", "author": "The Curated Capsule", "publishedAt": "2026-11-16", "cover": "/images/articles/satin-after-dark/cover.jpg", "coverAlt": "Model in a silver satin slip dress and black opera gloves", "products": ["slip", "kitten-heels", "pendant"], "body": "Every December arrives with the same small panic: the calendar fills up, and the wardrobe somehow doesn't. The answer is not five new dresses. It is one very good slip dress, and a little imagination.\n\n## Version one: as it is\n\nBias-cut satin needs almost nothing. A fine pendant, a low heel, hair pulled back. The cut does the work, so let it. This is the dinner, the gallery opening, the evening that might go late.\n\n## Version two: over a knit\n\nPull a thin roll-neck on underneath and the same dress becomes something you can wear to an office party without a second thought. Black on silver, cream on champagne — keep the knit close-fitting so the satin still moves.\n\n![Black-and-white portrait of a model with windswept hair](/images/articles/satin-after-dark/backstage.jpg)\n\n*Keep hair and make-up simple; satin already catches the light.*\n\n## Version three: with tailoring\n\nA sharp jacket over the shoulders, sleeves empty, changes the whole mood. It is the most useful trick of the season, and it keeps you warm between the taxi and the door.\n\n> The best party outfit is the one you forget you are wearing.\n\n## Version four: the morning after\n\nUnder an oversized jumper with trainers and a long coat, the slip dress turns into a skirt. Nobody needs to know it was at a party twelve hours ago.\n"}$article$::jsonb, 1)
  on conflict (slug) do nothing
  returning id, slug, document
)
insert into public.articles (id, slug, document)
select id, slug, document from draft;

with draft as (
  insert into public.article_drafts (document, published_revision)
  values ($article${"title": "Colour for the grey months", "slug": "colour-for-the-grey-months", "emphasis": "grey months", "kicker": "Trend report", "dek": "Why a single bright piece does more for winter than any amount of black.", "author": "The Curated Capsule", "publishedAt": "2026-11-12", "cover": "/images/articles/colour-for-the-grey-months/cover.jpg", "coverAlt": "Model in a yellow puffer and sunglasses leaning against a red window frame", "products": ["anorak", "cuff", "mesh"], "body": "Winter wardrobes drift towards black and navy for good reasons: they are easy, they hide the weather, and they go with everything. But by the middle of January, a whole city dressed in the same three shades starts to feel like a long grey corridor.\n\n## One piece is enough\n\nYou do not need to dress head to toe in colour. One saturated piece — a yellow puffer, a red knit, a green bag — against an otherwise quiet outfit looks deliberate rather than loud. Outerwear is the easiest place to start, because it is the part everyone sees.\n\n![Model in an oversized red set against a clear blue sky](/images/articles/colour-for-the-grey-months/red.jpg)\n\n*Tonal dressing — one colour from top to bottom — is the confident version.*\n\n## Go tonal if you dare\n\nIf one piece feels too timid, try a single colour all the way through: red trousers with a red top, in slightly different shades. It sounds bold, but it is actually simpler than mixing, because nothing has to match exactly.\n\n> Bright colour in winter is not about being noticed. It is about feeling awake.\n\n## Keep the metal cool\n\nSilver jewellery and chrome accessories sit beautifully against strong colour, and they make even a familiar black coat feel new again.\n"}$article$::jsonb, 1)
  on conflict (slug) do nothing
  returning id, slug, document
)
insert into public.articles (id, slug, document)
select id, slug, document from draft;

with draft as (
  insert into public.article_drafts (document, published_revision)
  values ($article${"title": "Pack light: a weekend in Paris", "slug": "pack-light-a-weekend-in-paris", "emphasis": "Paris", "kicker": "Travel edit", "dek": "Ten pieces, one small bag, three days that look like you packed for a week.", "author": "The Curated Capsule", "publishedAt": "2026-11-08", "cover": "/images/articles/pack-light-a-weekend-in-paris/cover.jpg", "coverAlt": "Three models lying together on crumpled linen", "products": ["suit-jacket", "pleated-trousers", "slingback", "hobo-bag"], "body": "The secret to a stylish weekend away is not packing more. It is packing pieces that all work with each other, so every combination is an outfit. For three days in Paris, ten pieces and one cabin bag are plenty.\n\n## The list\n\n- A tailored jacket that works as a coat on milder days\n- Wide-leg trousers in black or navy\n- Dark straight jeans\n- Two knits: one fine, one chunky\n- Two shirts or T-shirts\n- One slip dress for dinner\n- A low heel and a pair of flats you can walk in all day\n- A bag big enough for a map, a book and a croissant\n\n## The rule of three colours\n\nChoose a base (black or navy), a light (cream or white) and one accent. Everything you pack should be one of those three. It sounds restrictive, but it means anything can go with anything, and getting dressed takes two minutes.\n\n![Two models in white sunglasses, one in a yellow graphic dress](/images/articles/pack-light-a-weekend-in-paris/street.jpg)\n\n*Let accessories carry the personality; the clothes can stay simple.*\n\n## Walk first, pose second\n\nParis is a walking city, and nothing ruins a weekend faster than shoes you have to think about. A low slingback or a polished loafer will take you from the Marais to dinner without a change.\n\n> Pack for the life you'll actually live there — mostly walking, sometimes dining, always coffee.\n"}$article$::jsonb, 1)
  on conflict (slug) do nothing
  returning id, slug, document
)
insert into public.articles (id, slug, document)
select id, slug, document from draft;
